form.script:
(function () {
    var video = document.getElementById('camera_video');
    var canvas = document.getElementById('photo_canvas');
    var hidden = document.getElementById('photo_data');
    var preview = document.getElementById('photo_preview');
    var status = document.getElementById('photo_status');
    var startBtn = document.getElementById('start_camera');
    var takeBtn = document.getElementById('take_photo');
    var fileInput = document.getElementById('photo_file');
    if (!canvas || !hidden) { return; }
    var stream = null;

    function stopCamera() {
        if (stream) {
            stream.getTracks().forEach(function (track) { track.stop(); });
            stream = null;
        }
        video.classList.add('d-none');
        takeBtn.classList.add('d-none');
    }

    startBtn.addEventListener('click', function () {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            status.textContent = 'Tu navegador no permite la cámara; usa Subir foto.';
            return;
        }
        navigator.mediaDevices.getUserMedia({video: {facingMode: 'user'}, audio: false})
            .then(function (mediaStream) {
                stream = mediaStream;
                video.srcObject = mediaStream;
                video.classList.remove('d-none');
                takeBtn.classList.remove('d-none');
                status.textContent = '';
            })
            .catch(function () {
                status.textContent = 'No se pudo abrir la cámara; usa Subir foto.';
            });
    });

    function draw(source, width, height) {
        var max = 640;
        var scale = Math.min(1, max / Math.max(width, height));
        canvas.width = Math.round(width * scale);
        canvas.height = Math.round(height * scale);
        var ctx = canvas.getContext('2d');
        ctx.drawImage(source, 0, 0, canvas.width, canvas.height);
        hidden.value = canvas.toDataURL('image/jpeg', 0.7);
        preview.src = hidden.value;
        preview.classList.remove('d-none');
        status.textContent = 'Foto lista para el expediente.';
    }

    takeBtn.addEventListener('click', function () {
        if (!stream) { return; }
        draw(video, video.videoWidth, video.videoHeight);
        stopCamera();
    });

    fileInput.addEventListener('change', function () {
        var file = fileInput.files[0];
        if (!file) { return; }
        var image = new Image();
        image.onload = function () {
            draw(image, image.width, image.height);
            URL.revokeObjectURL(image.src);
        };
        image.src = URL.createObjectURL(file);
    });
})();

